"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["26097"],{97393(e){e.exports=JSON.parse('{"id":"F449","slug":"reit-ffo-affo","name":"REIT Funds From Operations (FFO) and AFFO","subject":"Alternative Investments","section":"Alternatives","topic":"Real estate investing and REITs","level":"Beginner","aliases":["FFO","AFFO","P/FFO","REIT payout ratio"],"formula":{"latex":"FFO=NI+D\\\\&A-G,\\\\quad AFFO=FFO-CapEx-SLR,\\\\quad \\\\frac{P}{FFO}","also":[],"text":"FFO = net income + depreciation and amortization - gains on property sales; AFFO = FFO - recurring maintenance capital spending - straight-line rent adjustments; Price / FFO = share price / FFO per share; Payout ratio = dividend per share / AFFO per share"},"symbols":[{"symbol":"NI","meaning":"Net income","unit":"money"},{"symbol":"D&A","meaning":"Depreciation and amortization of buildings (a non-cash charge that overstates real wear on property)","unit":"money"},{"symbol":"G","meaning":"Gains on property sales (one-off, removed)","unit":"money"},{"symbol":"CapEx","meaning":"Recurring spending to keep buildings leasable","unit":"money"},{"symbol":"SLR","meaning":"Straight-line rent adjustment: rent booked as income but not yet received in cash","unit":"money"}],"when_to_use":"Use it to assess a REIT instead of ordinary earnings. Accounting depreciation falls on buildings that often hold or gain value, so net income understates the cash a REIT earns. FFO adds it back; AFFO goes further and removes the spending needed to keep the properties let. The payout ratio against AFFO shows whether the dividend is covered.","worked_example":{"problem":"A REIT reports net income of 120m, depreciation of 90m and a 25m gain on property sales. Maintenance capex is 30m and the straight-line rent adjustment is 5m. It has 50m shares at a price of 40 and pays a dividend of 2.20.","inputs":{"ni":120,"d":90,"g":25,"c":30,"s":5,"sh":50,"p":40,"dv":2.2},"steps":[{"label":"FFO = NI + D&A - gains","working":"120+90-25","value":"185.00"},{"label":"AFFO = FFO - capex - straight-line adjustment","working":"185-30-5","value":"150.00"},{"label":"FFO per share","working":"185 / 50","value":"3.70"},{"label":"AFFO per share","working":"150 / 50","value":"3.00"},{"label":"Price / FFO","working":"40 / 3.7","value":"10.81"},{"label":"Payout ratio = dividend / AFFO per share","working":"2.2 / 3","value":"73.3%"},{"label":"Dividend covered? (1 = yes)","working":"1 if 2.2<=3 else 0","value":"1"}],"answer":"FFO is 185.00m and AFFO is 150.00m. Per share, FFO is 3.70 and AFFO is 3.00. The price is 10.81 times FFO. The dividend uses 73.3% of AFFO, so it is 1 (1 = covered by AFFO, 0 = not covered)."},"calculator":{"available":true,"inputs":[{"id":"ni","label":"Net income (millions)","unit":"money","type":"number","default":120,"hint":""},{"id":"d","label":"Depreciation and amortization (millions)","unit":"money","type":"number","default":90,"hint":""},{"id":"g","label":"Gains on property sales (millions)","unit":"money","type":"number","default":25,"hint":""},{"id":"c","label":"Maintenance capex (millions)","unit":"money","type":"number","default":30,"hint":""},{"id":"s","label":"Straight-line rent adjustment (millions)","unit":"money","type":"number","default":5,"hint":""},{"id":"sh","label":"Shares (millions)","unit":"","type":"number","default":50,"hint":"","min":0.01},{"id":"p","label":"Share price","unit":"money","type":"number","default":40,"hint":""},{"id":"dv","label":"Dividend per share","unit":"money","type":"number","default":2.2,"hint":""}],"checks":[{"expr":"sh>0 and p>0","message":"Shares and price must be above zero."}],"steps":[{"id":"ffo","label":"FFO = NI + D&A - gains","expr":"ni+d-g","format":"num2"},{"id":"affo","label":"AFFO = FFO - capex - straight-line adjustment","expr":"ffo-c-s","format":"num2"},{"id":"ffops","label":"FFO per share","expr":"ffo/sh","format":"num2"},{"id":"affops","label":"AFFO per share","expr":"affo/sh","format":"num2"},{"id":"pffo","label":"Price / FFO","expr":"p/ffops","format":"num2"},{"id":"pay","label":"Payout ratio = dividend / AFFO per share","expr":"dv/affops","format":"pct1"},{"id":"cov_","label":"Dividend covered? (1 = yes)","expr":"1 if dv<=affops else 0","format":"num0"}],"results":["ffo","affo","pffo","pay"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"ffo":185,"affo":150,"ffops":3.7,"affops":3,"pffo":10.81081081081081,"pay":0.7333333333333334,"cov_":1}},"finder":{"finds":"A REIT\'s cash earnings, valuation multiple and dividend cover","needs":"Net income, depreciation, gains, capex, rent adjustment, shares, price, dividend"},"related":[{"slug":"cap-rate-valuation","name":"Net Operating Income and Cap-Rate Valuation"},{"slug":"dividend-payout-ratio","name":"Dividend Payout Ratio"},{"slug":"pe-earnings-yield","name":"P/E Ratio and Earnings Yield"}],"related_ids":["F450","F175","F271"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>F</mi><mi>F</mi><mi>O</mi><mo>=</mo><mi>N</mi><mi>I</mi><mo>+</mo><mi>D</mi><mi mathvariant=\\"normal\\">&amp;</mi><mi>A</mi><mo>\u2212</mo><mi>G</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>A</mi><mi>F</mi><mi>F</mi><mi>O</mi><mo>=</mo><mi>F</mi><mi>F</mi><mi>O</mi><mo>\u2212</mo><mi>C</mi><mi>a</mi><mi>p</mi><mi>E</mi><mi>x</mi><mo>\u2212</mo><mi>S</mi><mi>L</mi><mi>R</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mfrac><mi>P</mi><mrow><mi>F</mi><mi>F</mi><mi>O</mi></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">FFO=NI+D\\\\&amp;A-G,\\\\quad AFFO=FFO-CapEx-SLR,\\\\quad \\\\frac{P}{FFO}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"reinsurance-recoveries","name":"Reinsurance: Quota Share and Excess of Loss"},"next":{"slug":"rsi","name":"Relative Strength Index (RSI)"},"lesson":null,"total":522}')}}]);